<?php $page_title='Patient';require_once __DIR__.'/../includes/header.php';$id=(int)$_GET['id'];$s=$pdo->prepare("SELECT * FROM patients WHERE id=?");$s->execute([$id]);$p=$s->fetch();if(!$p)die('Patient not found');$records=$pdo->prepare("SELECT r.*,d.name doctor FROM medical_records r JOIN doctors d ON d.id=r.doctor_id WHERE r.patient_id=? ORDER BY r.id DESC");$records->execute([$id]);?>
<div class="d-flex justify-content-between"><h2><?=e($p['name'])?> <small class="text-muted"><?=$p['patient_code']?></small></h2><a href="../appointments/add.php?patient_id=<?=$id?>" class="btn btn-primary">+ Appointment</a></div><div class="row g-3 mt-1"><div class="col-md-5"><div class="card p-4"><h5>Patient Information</h5><p>Gender: <?=$p['gender']?></p><p>Age: <?=$p['age']?></p><p>Phone: <?=$p['phone']?></p><p>Blood Group: <?=$p['blood_group']?></p><p>Address: <?=e($p['address'])?></p></div></div><div class="col-md-7"><div class="card p-4"><h5>Medical Records</h5><?php foreach($records as $r):?><div class="border-bottom py-2"><b><?=$r['visit_date']?> — <?=e($r['doctor'])?></b><br>Diagnosis: <?=e($r['diagnosis'])?><br>Notes: <?=e($r['notes'])?></div><?php endforeach;?></div></div></div><?php require_once __DIR__.'/../includes/footer.php';?>